Set-Location -LiteralPath $PSScriptRoot
$msg = 'booking links: short opaque token instead of the payload-in-URL design. The token was base64(json(lead, appt_type, duration, expires)) plus a truncated signature - 379 characters carrying the family name, phone and tier in the URL. That made a normal Restland SMS 602 characters / 4 segments and carriers filtered it: Twilio 30007 on every multi-segment send from the 10DLC number since July, while a 1-segment message on the same path to the same handset delivered. Token is now secrets.token_urlsafe(16) - 22 characters, 128 bits, no payload, no secret needed and unforgeable by construction, versus a 64-bit truncated hash over a readable payload. Appointment label, duration and expiry move onto the booking_links row the token already keys; every lookup was already token-equality and lead/advisor were always read from the row. calendar_router prefers the stored columns and keeps the legacy base64 decode as a fallback so links already in families hands still open. A real message with a booking link is now 1-2 segments.'
& "$PSScriptRoot\deploy.ps1" -Message $msg
Write-Output ("DEPLOY_EXIT=" + $LASTEXITCODE)
